"""L10M-ORACLE-3 closed-loop target policy."""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety gating, short-term target confirmation, and hysteretic steering."""
    memory = dict(memory or {})

    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    last_action = memory.get("last_action", "")
    near_streak = int(memory.get("near_streak", 0))
    lost_streak = int(memory.get("lost_streak", 0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    # Hard safety gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        memory["near_streak"] = 0
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )

    if not confirmed:
        memory["near_streak"] = 0
        lost_streak = max(lost_streak + 1, lost_steps)
        memory["lost_streak"] = lost_streak

        if state in {"LOCKED", "APPROACH", "REACQUIRE"} or lost_streak <= 1:
            return emit("STOP", 0.92, "REACQUIRE")

        action = scan_direction
        memory["scan_direction"] = (
            "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
        )
        return emit(action, 0.74, "SEARCH")

    memory["lost_streak"] = 0
    if track_age < 2:
        memory["near_streak"] = 0
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if heading_error <= 12.0 and identity_confidence >= 0.80:
            near_streak += 1
            memory["near_streak"] = near_streak
            if near_streak >= 2:
                return emit("ARRIVED", 0.97, "ARRIVED")
            return emit("SLOW_DOWN", 0.90, "VERIFY")
        memory["near_streak"] = 0
        action = "VEER_LEFT" if bearing < 0 else "VEER_RIGHT"
        return emit(action, 0.87, "APPROACH")

    memory["near_streak"] = 0
    if bearing < -12.0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.89, "APPROACH")
    if bearing > 12.0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.89, "APPROACH")

    # Keep a previous correction through the deadband when it remains safe,
    # reducing left/right instruction thrashing.
    if abs(bearing) <= 12.0:
        if last_action == "VEER_LEFT" and observation["corridor_left"] and bearing < -4.0:
            return emit("VEER_LEFT", 0.84, "APPROACH")
        if last_action == "VEER_RIGHT" and observation["corridor_right"] and bearing > 4.0:
            return emit("VEER_RIGHT", 0.84, "APPROACH")
        if observation["corridor_center"]:
            return emit("FORWARD", 0.91, "APPROACH")

    if observation["corridor_center"]:
        return emit("FORWARD", 0.89, "APPROACH")
    if bearing < 0 and observation["corridor_left"]:
        return emit("VEER_LEFT", 0.81, "APPROACH")
    if bearing > 0 and observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.81, "APPROACH")
    if observation["corridor_left"]:
        return emit("VEER_LEFT", 0.78, "APPROACH")
    if observation["corridor_right"]:
        return emit("VEER_RIGHT", 0.78, "APPROACH")

    return emit("STOP", 0.98, "STOPPED")


# EVOLVE-BLOCK-END
